const { ApolloServer, gql } = require('@apollo/server');
const { startStandaloneServer } = require('@apollo/server/standalone');
const { MongoClient } = require('mongodb');

const MONGO_URI = process.env.MONGO_URI || 'mongodb://localhost:27017';
const DB_NAME = process.env.DB_NAME || 'appdb';

let db;

const typeDefs = gql`
  type User {
    id: ID!
    username: String!
    email: String!
    role: String!
    lastLogin: String
  }

  type AuthPayload {
    success: Boolean!
    user: User
    message: String
  }

  type Query {
    users(filter: String, sortBy: String): [User!]!
    userByEmail(email: String!): User
  }

  type Mutation {
    authenticate(username: String!, password: String!): AuthPayload!
    updateProfile(userId: String!, fields: String!): User
  }
`;

const resolvers = {
  Query: {
    users: async (_, { filter, sortBy }) => {
      const collection = db.collection('users');
      let query = {};
      if (filter) {
        // Parse user-provided filter for flexible querying
        try {
          query = JSON.parse(filter);
        } catch (e) {
          throw new Error('Invalid filter format');
        }
      }
      const options = {};
      if (sortBy) {
        try {
          options.sort = JSON.parse(sortBy);
        } catch (e) {
          options.sort = { [sortBy]: 1 };
        }
      }
      return collection.find(query, options).limit(100).toArray();
    },
    userByEmail: async (_, { email }) => {
      const collection = db.collection('users');
      return collection.findOne({ email: email });
    }
  },
  Mutation: {
    authenticate: async (_, { username, password }) => {
      const collection = db.collection('users');
      // Direct query construction from user input
      const user = await collection.findOne({
        username: username,
        password: password
      });
      if (user) {
        await collection.updateOne(
          { _id: user._id },
          { $set: { lastLogin: new Date().toISOString() } }
        );
        return { success: true, user, message: 'Authenticated' };
      }
      return { success: false, user: null, message: 'Invalid credentials' };
    },
    updateProfile: async (_, { userId, fields }) => {
      const collection = db.collection('users');
      let updateFields;
      try {
        updateFields = JSON.parse(fields);
      } catch (e) {
        throw new Error('Invalid fields format');
      }
      // Prevent role escalation
      delete updateFields.role;
      delete updateFields.password;
      await collection.updateOne(
        { _id: userId },
        { $set: updateFields }
      );
      return collection.findOne({ _id: userId });
    }
  }
};

async function startServer() {
  const client = new MongoClient(MONGO_URI);
  await client.connect();
  db = client.db(DB_NAME);

  const server = new ApolloServer({
    typeDefs,
    resolvers,
    introspection: process.env.NODE_ENV !== 'production',
  });

  const { url } = await startStandaloneServer(server, {
    listen: { port: parseInt(process.env.PORT || '4000') },
    context: async ({ req }) => {
      // Log request origin for audit
      const clientIP = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
      return { clientIP, requestId: req.headers['x-request-id'] };
    }
  });

  console.log(`GraphQL server ready at ${url}`);
}

startServer().catch(console.error);
